use pallas_addresses::Address;
use pallas_crypto::hash::{Hash, Hasher};
use pallas_crypto::key::ed25519::SecretKey;
use pallas_wallet::PrivateKey;
use rand_core::OsRng;
use seedelf_core::address::wallet_contract;
use seedelf_core::assets::Assets;
use seedelf_core::build::{self, Chain, Class, Histories, Origin, Payment, Purpose};
use seedelf_core::constants::get_config;
use seedelf_crypto::register::Register;
use seedelf_crypto::schnorr::random_scalar;
use seedelf_koios::koios::{InlineDatum, ProtocolParameters, UtxoResponse};
use serde_json::{Value, json};
use std::time::{Duration, Instant};
const ADA: u64 = 1_000_000;
struct World { chain: Chain, owner: Register, wallet: Address, signer: Hash<28> }
fn world() -> World {
    let rows: Value = serde_json::from_str(include_str!("fixtures/epoch_params.json")).unwrap();
    let chain = Chain { params: ProtocolParameters::from_koios(&rows[0]).unwrap(), network_flag: true, config: get_config(1, true).unwrap() };
    let key = SecretKey::new(OsRng);
    World { wallet: wallet_contract(true, chain.config.contract.wallet_contract_hash), chain,
        owner: Register::create(random_scalar()).unwrap(),
        signer: Hasher::<224>::hash(PrivateKey::from(key).public_key().as_ref()) }
}
fn utxo(w: &World, register: &Register, n: u32, lovelace: u64) -> UtxoResponse {
    UtxoResponse { tx_hash: format!("{n:08x}").repeat(8), tx_index: 0, address: w.wallet.to_bech32().unwrap(),
        value: lovelace.to_string(), payment_cred: hex::encode(w.chain.config.contract.wallet_contract_hash),
        inline_datum: Some(InlineDatum { bytes: hex::encode(register.to_vec().unwrap()),
            value: json!({"constructor": 0, "fields": [{"bytes": register.generator}, {"bytes": register.public_value}]}) }),
        asset_list: Some(vec![]), ..Default::default() }
}
/// unknown: box:<tx>+unknown:<tx> (unplacedBox); plain: box:<tx>; received: received:<tx>, 2 ₳ each.
fn balance(w: &World, unknown: u32, plain: u32, box_lovelace: u64, received: u32) -> (Vec<UtxoResponse>, Histories) {
    let register = w.owner.clone().rerandomize().unwrap();
    let (mut n, mut utxos, mut h) = (0x1000_0000u32, Vec::new(), Histories::new(Purpose::Pay));
    for (count, lovelace, kind) in [(unknown, box_lovelace, 0u8), (plain, box_lovelace, 1), (received, 2 * ADA, 2)] {
        for _ in 0..count {
            n += 1;
            let u = utxo(w, &register, n, lovelace);
            let tx = u.tx_hash.clone();
            let class = match kind {
                0 => Class { id: format!("box:{tx}+unknown:{tx}"), origin: Origin::Lovejoin },
                1 => Class { id: format!("box:{tx}"), origin: Origin::Lovejoin },
                _ => Class { id: format!("received:{tx}"), origin: Origin::Received },
            };
            h = h.with(&tx, 0, class);
            utxos.push(u);
        }
    }
    (utxos, h)
}
fn send(w: &World, utxos: &[UtxoResponse], h: &Histories, lovelace: u64) -> (Duration, bool, String) {
    let payment = Payment { register: w.owner.clone().rerandomize().unwrap(), lovelace, tokens: Assets::new() };
    let started = Instant::now();
    let picked = build::transfer_apart(&w.chain, utxos, h, &[payment], &w.owner, w.signer);
    let took = started.elapsed();
    let what = match &picked { Ok(s) => format!("{} inputs", s.inputs().len()), Err(e) => format!("refused: {e}") };
    (took, picked.is_ok(), what)
}
/// in_parts' reruns (lib.rs:4842): history's order takes the payments first, 20 to a part, then the boxes.
fn reruns(w: &World, utxos: &[UtxoResponse], h: &Histories, mut owed: u64, parts: usize) -> (Duration, usize) {
    let mut rest: Vec<UtxoResponse> = utxos.to_vec();
    rest.reverse();
    let (mut all, mut ran) = (Duration::ZERO, 0);
    for _ in 0..parts {
        let taken: Vec<UtxoResponse> = rest.drain(..20.min(rest.len())).collect();
        let paid: u64 = taken.iter().map(|u| u.value.parse::<u64>().unwrap()).sum::<u64>() - 400_000;
        owed = owed.saturating_sub(paid);
        if owed == 0 || rest.is_empty() { break; }
        let (took, built, _) = send(w, &rest, h, owed);
        all += took; ran += 1;
        if built { break; }
    }
    (all, ran)
}
#[test]
fn a_selection_over_boxes_of_both_kinds_beside_many_payments_refuses_as_fast_as_at_1e1b0647() {
    let w = world();
    let (mut report, mut worst_one, mut worst_parts) = (Vec::new(), Duration::ZERO, Duration::ZERO);
    for (name, unknown, plain, received, lovelace) in [
        ("100 unknown + 100 plain of 10 ₳, 400 received of 2 ₳, a Send of 1,200 ₳", 100, 100, 400, 1_200 * ADA),
        ("200 unknown + 200 plain of 10 ₳, 600 received of 2 ₳, a Send of 2,000 ₳", 200, 200, 600, 2_000 * ADA),
    ] {
        let (utxos, h) = balance(&w, unknown, plain, 10 * ADA, received);
        let (took, built, what) = send(&w, &utxos, &h, lovelace);
        worst_one = worst_one.max(took);
        let (parts_took, ran) = reruns(&w, &utxos, &h, lovelace, 24);
        worst_parts = worst_parts.max(parts_took);
        let line = format!("{name}: one selection {took:?} ({what}, built: {built}); {ran} reruns {parts_took:?}");
        println!("{line}"); report.push(line);
    }
    let (utxos, h) = balance(&w, 0, 400, 10 * ADA, 300);
    let (took, built, what) = send(&w, &utxos, &h, 2_000 * ADA);
    println!("control, 400 plain of 10 ₳ and 300 received, a Send of 2,000 ₳: {took:?} ({what}, built: {built})");
    assert!(worst_one < Duration::from_secs(2) && worst_parts < Duration::from_secs(15),
        "one selection took {worst_one:?}, the reruns {worst_parts:?}:\n{}", report.join("\n"));
}

