```rust
/// l6reference#2: a box of ADA alone weighing a little more than a token pool's way back (its ADA less its token's
/// least) pays less beside the same money. O 3 ₳ made private; T a mixed token pool's way back, 7.5 ₳ and its token;
/// B a plain way back of 6.6 ₳; C 4.71 ₳. 8 ₳ out: O and T pay with one box, O and B are short.
#[test]
fn l6reference_2_a_token_box_that_pays_goes_before_an_ada_box_weighing_more_that_doesnt() {
    let w = world();
    let o = owned(&w, 0x01, 0, 3_000_000, &[]);
    let t = owned(&w, 0x70, 0, 7_500_000, &[("poolA", 1)]);
    let b = owned(&w, 0x61, 0, 6_600_000, &[]);
    let c = owned(&w, 0x62, 0, 4_710_000, &[]);
    let labels = [(&o, "O"), (&t, "T"), (&b, "B"), (&c, "C")];
    let name_of = |s: &String| -> &'static str {
        labels.iter().find(|(u, _)| &one(u)[0] == s).map_or("?", |(_, n)| *n)
    };
    let t_class = class(&format!("box:{}", t.tx_hash), Origin::Mixed);
    let b_class = class(&format!("box:{}", b.tx_hash), Origin::Lovejoin);
    let (t_weight, _) = build::box_weight(&w.chain.params, &t_class, &[&t]);
    let (b_weight, _) = build::box_weight(&w.chain.params, &b_class, &[&b]);
    // At 26794c40, T weighs 5,870,820 (7.5 ₳ less its token's least), less than B.
    println!("T weighs {t_weight} (holds 7500000), B weighs {b_weight}");
    let known: Vec<(&UtxoResponse, Class)> = vec![
        (&o, class("public:0", Origin::Own)),
        (&t, t_class.clone()),
        (&b, b_class.clone()),
        (&c, class(&format!("box:{}", c.tx_hash), Origin::Lovejoin)),
    ];
    let one_box = outpoints(&[o.clone(), t.clone()]);
    let mut wrong = Vec::new();
