```rust
//! l6words#3 (round six's last look): a token pool's way back T, weighed by what it adds (its ADA less its token's
//! least), weighs less than A, a box of ADA alone, yet pays more beside the change the spend makes anyway. At the input
//! limit, 21 UTxOs made private beside T pay in one transaction (1e1b0647 built that: T was other money then); beside
//! A they're short, and with both they're 23 inputs, too many. Every order that holds T also holds A, so the spend is
//! refused as too many (and the web wallet sends it in parts).

use pallas_addresses::{
    Address, Network, PaymentKeyHash, ShelleyAddress, ShelleyDelegationPart, ShelleyPaymentPart,
};
use pallas_crypto::hash::{Hash, Hasher};
use pallas_crypto::key::ed25519::SecretKey;
use pallas_wallet::PrivateKey;
use rand_core::OsRng;
use seedelf_core::address::wallet_contract;
use seedelf_core::assets::Assets;
use seedelf_core::build::{
    self, AddressPayment, Chain, Class, Histories, Origin, Payment, Purpose,
};
use seedelf_core::constants::get_config;
use seedelf_crypto::register::Register;
use seedelf_crypto::schnorr::random_scalar;
use seedelf_koios::koios::{Asset, InlineDatum, ProtocolParameters, UtxoResponse};
use serde_json::{Value, json};

const TOKEN_POLICY: &str = "c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0c0";
const ADA: u64 = 1_000_000;

fn chain() -> Chain {
    let rows: Value = serde_json::from_str(include_str!("fixtures/epoch_params.json")).unwrap();
    Chain { params: ProtocolParameters::from_koios(&rows[0]).unwrap(), network_flag: true, config: get_config(1, true).unwrap() }
}

struct World { chain: Chain, owner: Register, wallet: Address, signer: Hash<28>, to: Address }

fn world() -> World {
    let chain = chain();
    let key = SecretKey::new(OsRng);
    World {
        wallet: wallet_contract(true, chain.config.contract.wallet_contract_hash),
        chain,
        owner: Register::create(random_scalar()).unwrap(),
        signer: Hasher::<224>::hash(PrivateKey::from(key).public_key().as_ref()),
        to: ShelleyAddress::new(Network::Testnet, ShelleyPaymentPart::Key(PaymentKeyHash::new([7; 28])), ShelleyDelegationPart::Null).into(),
    }
}

/// A wallet-contract UTxO of `w`'s, made by transaction `n`, with one of `token` where given, as Koios returns it.
fn utxo(w: &World, n: u8, lovelace: u64, token: Option<&str>) -> UtxoResponse {
    let register = w.owner.clone().rerandomize().unwrap();
    UtxoResponse {
        tx_hash: hex::encode([n; 32]),
        tx_index: 0,
        address: w.wallet.to_bech32().unwrap(),
        value: lovelace.to_string(),
        payment_cred: hex::encode(w.chain.config.contract.wallet_contract_hash),
        inline_datum: Some(InlineDatum {
            bytes: hex::encode(register.to_vec().unwrap()),
            value: json!({"constructor": 0, "fields": [{"bytes": register.generator}, {"bytes": register.public_value}]}),
        }),
        asset_list: Some(token.map(|name| Asset { decimals: 0, quantity: "1".into(), policy_id: TOKEN_POLICY.to_string(), asset_name: hex::encode(name), fingerprint: String::new() }).into_iter().collect()),
        ..Default::default()
    }
}

#[derive(Debug, Clone, Copy)]
enum Spend { Send, Public, Fund }

impl Spend {
    fn purpose(self) -> Purpose {
        match self { Spend::Fund => Purpose::Fund { session: Some("session:7".into()) }, _ => Purpose::Pay }
    }
    fn to(w: &World, lovelace: u64) -> AddressPayment { AddressPayment { to: w.to.clone(), lovelace, tokens: Assets::new() } }
    fn payments(self, w: &World, lovelace: u64) -> (Vec<Payment>, Vec<AddressPayment>) {
        match self {
            Spend::Send => (vec![Payment { register: w.owner.clone().rerandomize().unwrap(), lovelace, tokens: Assets::new() }], Vec::new()),
            Spend::Public => (Vec::new(), vec![Self::to(w, lovelace)]),
            Spend::Fund => (Vec::new(), vec![Self::to(w, lovelace), Self::to(w, 5 * ADA)]),
        }
    }
    /// Exactly `inputs`, as selection's own attempt builds them.
    fn from(self, w: &World, inputs: &[UtxoResponse], lovelace: u64) -> anyhow::Result<()> {
        let (seedelfs, addresses) = self.payments(w, lovelace);
        if addresses.is_empty() { build::transfer_from(&w.chain, inputs, &seedelfs, &w.owner, w.signer) }
        else { build::sweep_many_from(&w.chain, inputs, &addresses, &w.owner, w.signer) }
        .and_then(|s| s.estimate().map(|_| ()))
    }
    /// Selection's pick from `available`.
    fn apart(self, w: &World, available: &[UtxoResponse], h: &Histories, lovelace: u64) -> anyhow::Result<Vec<UtxoResponse>> {
        let (seedelfs, addresses) = self.payments(w, lovelace);
        if addresses.is_empty() { build::transfer_apart(&w.chain, available, h, &seedelfs, &w.owner, w.signer) }
        else { build::sweep_many_apart(&w.chain, available, h, &addresses, &w.owner, w.signer) }
        .map(|s| s.inputs().to_vec())
    }
}

#[test]
fn a_token_pools_way_back_that_pays_more_than_a_heavier_box_of_ada_alone_still_pays_in_one_at_the_input_limit() {
    let w = world();
    // 21 UTxOs made private from account 0, 50 ₳ each.
    let money: Vec<UtxoResponse> = (0..21u8).map(|i| utxo(&w, 0x10 + i, 50 * ADA, None)).collect();
    // A: a plain way back of 6 ₳, ADA alone. T: a token pool's way back of 7 ₳ holding its token.
    let a = utxo(&w, 0x01, 6 * ADA, None);
    let t = utxo(&w, 0x02, 7 * ADA, Some("poolA"));
    let with = |extra: &[&UtxoResponse]| -> Vec<UtxoResponse> { money.iter().cloned().chain(extra.iter().map(|u| (*u).clone())).collect() };
    let (adds_a, adds_t) = (build::adds(&w.chain.params, &a).unwrap(), build::adds(&w.chain.params, &t).unwrap());
    println!("adds: A {adds_a}, T {adds_t}");
    // The premise of the weighing: T weighs less than A.
    assert!(adds_t < adds_a, "T weighs {adds_t}, A {adds_a}");
    let mut wrong = Vec::new();
    for spend in [Spend::Send, Spend::Public, Spend::Fund] {
        // The most the 21 and T pay (a token's change never comes to nothing, so this is monotone).
        let (mut lo, mut hi) = (1_000 * ADA, 1_060 * ADA);
        assert!(spend.from(&w, &with(&[&t]), lo).is_ok());
        assert!(spend.from(&w, &with(&[&t]), hi).is_err());
        while hi - lo > 1 { let mid = lo + (hi - lo) / 2; if spend.from(&w, &with(&[&t]), mid).is_ok() { lo = mid } else { hi = mid } }
        let most_with_t = lo;
        // A tenth of an ADA under it: the 21 and T pay, the 21 and A are short, all 23 are too many.
        let p = most_with_t - ADA / 10;
        spend.from(&w, &with(&[&t]), p).expect("the 21 and T pay (22 inputs)");
        let beside_a = spend.from(&w, &with(&[&a]), p).unwrap_err();
        assert!(build::is_short(&beside_a), "{spend:?}: beside A: {beside_a}");
        let all = spend.from(&w, &with(&[&a, &t]), p).unwrap_err();
        assert!(build::is_too_many(&all), "{spend:?}: all 23: {all}");
        // The most the 21 and A pay, with change.
        let (mut lo_a, mut hi_a) = (1_000 * ADA, p);
        while hi_a - lo_a > 1 { let mid = lo_a + (hi_a - lo_a) / 2; if spend.from(&w, &with(&[&a]), mid).is_ok() { lo_a = mid } else { hi_a = mid } }
        println!("{spend:?}: the 21 and T pay up to {most_with_t}, the 21 and A up to {lo_a}: {} lovelace only T's set pays", most_with_t - lo_a);
        for (a_origin, t_origin) in [(Origin::Lovejoin, Origin::Lovejoin), (Origin::Lovejoin, Origin::Mixed), (Origin::Mixed, Origin::Lovejoin)] {
            let h = money.iter()
                .fold(Histories::new(spend.purpose()), |h, u| h.with(&u.tx_hash, u.tx_index, Class { id: "public:0".into(), origin: Origin::Own }))
                .with(&a.tx_hash, a.tx_index, Class { id: format!("box:{}", a.tx_hash), origin: a_origin })
                .with(&t.tx_hash, t.tx_index, Class { id: format!("box:{}", t.tx_hash), origin: t_origin });
            let available = with(&[&a, &t]);
            let has = |inputs: &[UtxoResponse], u: &UtxoResponse| inputs.iter().any(|i| i.tx_hash == u.tx_hash);
            let line = match spend.apart(&w, &available, &h, p) {
                Ok(inputs) if inputs.len() == 22 && has(&inputs, &t) && !has(&inputs, &a) => {
                    println!("{spend:?} of {p} lovelace, A {a_origin:?}, T {t_origin:?}: built in one with the 21 and T");
                    continue;
                }
                Ok(inputs) => format!("{spend:?} of {p} lovelace, A {a_origin:?}, T {t_origin:?}: built with {} inputs, T {}, A {}", inputs.len(), has(&inputs, &t), has(&inputs, &a)),
                Err(e) => format!("{spend:?} of {p} lovelace (the most the 21 and T pay: {most_with_t}), A {a_origin:?}, T {t_origin:?}: refused: {e}"),
            };
            println!("{line}");
            wrong.push(line);
        }
    }
    assert!(wrong.is_empty(), "a spend the 21 and T pay in one transaction is refused:\n{}", wrong.join("\n"));
}

