fn a_token_pools_way_back_beside_payments_at_the_input_limit_still_goes_in_one_transaction() {
    let w = world();
    let k = owned(&w, 0x61, SMALL, &[]);
    let t = owned(&w, 0x70, TOKEN_BOX, &[("pooltoken", 1)]);
    weighs_less(&w, &t, &k);
    let received: Vec<UtxoResponse> = (0..21u8).map(|i| owned(&w, 0x10 + i, 5 * ADA, &[])).collect();
    let with = |boxes: &[&UtxoResponse], n: usize| -> Vec<UtxoResponse> {
        boxes.iter().map(|u| (*u).clone()).chain(received[..n].iter().cloned()).collect() };
    let mut wrong = Vec::new();
    for (name, seedelf) in [("a Send of 108 ₳ to one Seedelf", vec![paying(108 * ADA)]),
        ("a Send of 54 ₳ to each of two Seedelfs", vec![paying(54 * ADA), paying(54 * ADA)])] {
        pays_with(&w, &with(&[&t], 21), &seedelf, &[]).unwrap_or_else(|e| panic!("{name}: the 21 and T must pay: {e}"));
        assert!(short(pays_with(&w, &with(&[&k], 21), &seedelf, &[])), "{name}: the 21 and K must be short");
        assert!(short(pays_with(&w, &with(&[&k, &t], 20), &seedelf, &[])), "{name}: K, T and 20 must be short");
        assert!(pays_with(&w, &with(&[&k, &t], 21), &seedelf, &[]).is_err_and(|e| build::is_too_many(&e)), "{name}: K, T and the 21 must be too many");
        for t_origin in [Origin::Mixed, Origin::Lovejoin] {
            let mut known = vec![(&k, class(&format!("box:{}", k.tx_hash), Origin::Lovejoin)),
                (&t, class(&format!("box:{}", t.tx_hash), t_origin))];
            known.extend(received.iter().map(|r| (r, class(&format!("received:{}", r.tx_hash), Origin::Received))));
            let line = match selected(&w, Purpose::Pay, &known, &seedelf, &[]) {
                Ok(s) if outpoints(&s) == outpoints(&with(&[&t], 21)) => continue,
