                Err(e) => format!("{name}, T {t_origin:?}: refused (too many: {}): {e}", build::is_too_many(&e)),
            };
            println!("{line}"); wrong.push(line);
        }
    }
    assert!(wrong.is_empty(), "rule 1 fails: what went as one transaction is refused (a Send in parts, two Seedelfs refused):\n{}", wrong.join("\n"));
}

